return ['domain'=>'presspermit-pron%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2;','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11 ? 0 : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1 : 2);','language'=>'hr>= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1: 2);','project-id-version'=>'PublishPress Permissions Pro 4.8.1','pot-creation-date'=>'2026-04-02T18:54:49+00:00','po-revision-date'=>'2026-10-01 19:50+0000','x-generator'=>'Weblate 2026.6.1','messages'=>['PublishPress Permissions Pro'=>'PublishPress Permissions Pro','https://publishpress.com/permissions'=>'https://publishpress.com/permissions','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'PublishPress Permissions omogućuje vam da omogućite ili odbijete pristup objavama, stranicama, kategorijama, oznakama i još mnogo toga.','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','Should pages with privacy status "premium" require set_pages_premium and edit_premium_pages capabilities? If so, you can %1$sassign a status-specific Page Editor role%2$s or %3$sadd the capabilities directly to a role%4$s.'=>'Trebaju li stranice s privatnim statusom "premium" zahtijevati set_pages_premium i edit_premium_pages mogućnosti? Ako da, možete %1$sdodijeliti ulogu urednika stranica specifičnu za status%2$s ili %3$sdodati mogućnosti izravno ulozi%4$s.','Note: Workflow sequence and branching for pre-publication is configured %son a separate screen%s'=>'Napomena: Sekvenca radnog toka i grananje za preobjavu je konfigurirano %son a separate screen%s','Additional settings provided by the %s module.'=>'Dodatne postavke pruža %s modul.','Note: If you deactive, re-entry of the license key will be required for re-activation.'=>'Napomena: Ako deaktivirate, ponovni unos ključa licence bit će potreban za ponovnu aktivaciju.','If enabled, custom group membership is applied network-wide (though role assignments are still site-specific).'=>'Ako je omogućeno, prilagođeno članstvo u grupi primjenjuje se na razini mreže (iako su dodijeljene uloge još uvijek specifične za stranicu).','Can create network-wide permission groups'=>'Može kreirati grupe dozvola na razini mreže','If group editing is allowed, can also modify network group membership'=>'Ako je uređivanje grupa dopušteno, također može modificirati članstvo u mrežnim grupama','This feature will control direct URL access to files in /uploads/ folder. By default, files are blocked if they are attached to a post which the user can\'t view.'=>'Ova značajka će kontrolirati izravni URL pristup datotekama u /uploads/ mapi. Prema zadanim postavkama, datoteke su blokirane ako su povezane s objavom koju korisnik ne može vidjeti.','File Access on multisite installations will require the following rules to be inserted above the stock ms-files.php rules in the %1$smain .htaccess file%2$s:'=>'Pristup datotekama na multisite instalacijama zahtijevat će da se sljedeća pravila umetnu iznad osnovnih ms-files.php pravila u %1$smain .htaccess datoteci%2$s:','But your .htaccess is missing or not writeable!'=>'No, vaša .htaccess datoteka nedostaje ili nije moguće pisati!','.htaccess needs to be updated to include these rules.'=>'.htaccess treba ažurirati kako bi uključio ova pravila.','.htaccess file has all required rules.'=>'.htaccess datoteka ima sva potrebna pravila.','These rules will not be inserted automatically.  You are responsible for editing .htaccess and later removing the rules if the functionality is no longer desired.'=>'Ova pravila neće biti umetnuta automatski. Vi ste odgovorni za uređivanje .htaccess i naknadno uklanjanje pravila ako funkcionalnost više nije željena.','Note that an additional rule will need to be added with each new site. %1$sTo eliminate this requirement, research "WordPress remove ms-files".%2$s'=>'Imajte na umu da će se dodatno pravilo morati dodati s svakom novom stranicom. %1$sKako biste uklonili ovaj zahtjev, istražite "WordPress remove ms-files".%2$s','You will need to manually restore the .htacces file to default contents if anything goes wrong. Proceed?'=>'Morat ćete ručno vratiti .htacces datoteku na zadani sadržaj ako nešto pođe po zlu. Nastaviti?','Update .htaccess now'=>'Ažurirajte .htaccess sada','only for sites with protected files'=>'samo za stranice s zaštićenim datotekama','for all sites'=>'za sve stranice','NONE: remove Permissions rules'=>'NIŠTA: uklonite pravila o dozvolama','Since the plugin is not network-activated, you will need to modify the .htaccess file manually, inserting a RewriteRule as shown above for each site which needs file filtering.'=>'Budući da dodatak nije aktiviran na mreži, morat ćete ručno izmijeniti .htaccess datoteku, umetnuvši RewriteRule kao što je prikazano iznad za svaku stranicu koja treba filtriranje datoteka.','This extends the File Access feature to files that are not attached to any post. This will not apply to user who have the edit_private_files or pp_list_all_files capability.'=>'Ovo proširuje značajku pristupa datotekama na datoteke koje nisu povezane s nijednom objavom. Ovo se neće primijeniti na korisnike koji imaju mogućnost edit_private_files ili pp_list_all_files.','Make attached files unreadable to users who do not have the edit_private_files or pp_list_all_files capability.'=>'Učinite povezane datoteke nečitljivima za korisnike koji nemaju mogućnost edit_private_files ili pp_list_all_files.','Improve Media Library performance by disabling file filtering for thumbnails (size specified in Settings > Media).'=>'Poboljšajte performanse Medijske biblioteke onemogućavanjem filtriranja datoteka za mini slike (veličina određena u Postavke > Mediji).','On some sites, an additional redirect is required to correctly deliver protected files. Leave this disabled for better performance if possible.'=>'Na nekim stranicama potrebna je dodatna preusmjeravanje za ispravno isporučivanje zaštićenih datoteka. Ostavite ovo onemogućeno za bolju izvedbu ako je moguće.','The File Access feature uses an %1$s.htaccess%2$s file located at %3$suploads/.htaccess%4$s. Normally no action is needed, but clicking the button below will update the URL keys (at next site access) that protect the files.'=>'Značajka pristupa datotekama koristi %1$s.htaccess%2$s datoteku smještenu u %3$suploads/.htaccess%4$s. Obično nije potrebna nikakva akcija, ali klikom na gumb ispod ažurirat će se URL ključevi (prilikom sljedećeg pristupa stranici) koji štite datoteke.','The File Access feature uses an %1$s.htaccess%2$s file located at %3$suploads/.htaccess%4$s. Normally no action is needed, but clicking the button below will update the URL keys that protect the files.'=>'Značajka pristupa datotekama koristi %1$s.htaccess%2$s datoteku smještenu u %3$suploads/.htaccess%4$s. Obično nije potrebna nikakva akcija, ali klikom na gumb ispod ažurirat će se URL ključevi koji štite datoteke.','Best practice is to access the above url periodically (using your own cron service) to prevent long-term bookmarking of protected files.'=>'Najbolja praksa je povremeno pristupiti gornjem URL-u (koristeći vlastitu cron uslugu) kako bi se spriječilo dugotrajno označavanje zaštićenih datoteka.','Supply a custom key which will enable a support url to regenerate file access keys.  Then execute the url regularly (using your own cron service) to prevent long-term bookmarking of protected files.'=>'Pružite prilagođeni ključ koji će omogućiti podržanom URL-u da regenerira ključeve za pristup datotekama. Zatim redovito izvršavajte URL (koristeći vlastitu cron uslugu) kako biste spriječili dugotrajno označavanje zaštićenih datoteka.','File Access can also protect files uploaded by FTP or other manual file copy, but does not detect them automatically. Click the button below to scan your uploads folder for files to protect.'=>'Pristup datotekama također može zaštititi datoteke prenesene putem FTP-a ili druge ručne kopije datoteka, ali ih ne prepoznaje automatski. Kliknite gumb ispod za skeniranje vaše mape s prijenosima za datoteke koje treba zaštititi.','Invalid file filtering key argument.'=>'Nevažeći argument ključa za filtriranje datoteka.','Please configure File Access options!'=>'Molimo konfigurirajte opcije pristupa datotekama!','The wp-content folder cannot be relocated outside the main WordPress folder.'=>'Mapa wp-content ne može se premjestiti izvan glavne WordPress mape.','Files linked in post content must be in %1$s (or a subfolder of it). If you move files, consider using a %2$s search and replace plugin%3$s to update those URLs.'=>'Datoteke povezane u sadržaju objave moraju biti u %1$s (ili podmapi). Ako premjestite datoteke, razmislite o korištenju %2$s dodatka za pretraživanje i zamjenu%3$s kako biste ažurirali te URL-ove.','File Access can also protect files uploaded by FTP or other manual processes, but does not detect them automatically. This utility can find and protect any uploaded files.'=>'Pristup datotekama također može zaštititi datoteke prenesene putem FTP-a ili drugih ručnih procesa, ali ih ne otkriva automatski. Ova alat može pronaći i zaštititi sve prenesene datoteke.','To run this utility by cron task or other direct request, use the following URL:'=>'Za pokretanje ovog alata putem cron zadatka ili drugog izravnog zahtjeva, upotrijebite sljedeći URL:','To run this utility by direct URL, set a file filtering regen key on Permissions Settings'=>'Za pokretanje ovog alata putem izravnog URL-a, postavite ključ filtriranja datoteka u Postavkama dozvola','Note: Direct access to uploaded file attachments cannot be filtered because your WP_CONTENT_DIR is not in the WordPress branch.'=>'Napomena: Izravan pristup učitanim privicima datoteka ne može se filtrirati jer vaš WP_CONTENT_DIR nije u WordPress grani.','The operation was terminated due to an invalid configuration.'=>'Operacija je prekinuta zbog nevažeće konfiguracije.','Checking %s posts / pages...'=>'Provjera %s objava / stranica...','%1$s skipping unfilterable file in %2$s "%3$s":%4$s %5$s'=>'%1$s preskočena nefiltrabilna datoteka u %2$s "%3$s":%4$s %5$s','%1$s skipping missing file in %2$s "%3$s":%4$s %5$s'=>'%1$s preskočena nedostajuća datoteka u %2$s "%3$s":%4$s %5$s','%1$sNew attachment in %2$s "%3$s":%4$s %5$s'=>'%1$sNovi privitak u %2$s "%3$s":%4$s %5$s','%s linked uploads were found in your post / page content.'=>'%s povezani uploadi pronađeni su u sadržaju vaše objave / stranice.','%s attachment records were added to the database.'=>'%s zapisa o privicima dodano je u bazu podataka.','All linked uploads are already registered as attachments.'=>'Svi povezani uploadi već su registrirani kao privici.','Statuses enabled here are available as Visibility options for post publishing. Affected posts become inaccessable without a corresponding status-specific role assignment.'=>'Statusi omogućeni ovdje dostupni su kao opcije vidljivosti za objavljivanje postova. Pogođeni postovi postaju nedostupni bez odgovarajuće dodjele uloge specifične za status.','Statuses enabled here are available in the editor as additional steps between Draft and Published.'=>'Statusi omogućeni ovdje dostupni su u uređivaču kao dodatni koraci između Nacrta i Objavljeno.','Statuses alter your content\'s accessibility by imposing additional capability requirements.'=>'Statusi mijenjaju dostupnost vašeg sadržaja nametajući dodatne zahtjeve za sposobnosti.','Enable Custom Capabilities by toggling the link below status name. If enabled, non-Editors will need a corresponding %ssupplemental role%s to edit posts of that status.'=>'Omogućite prilagođene sposobnosti prebacivanjem veze ispod imena statusa. Ako je omogućeno, ne-urednici će trebati odgovarajuću %ssupplentalnu ulogu%s za uređivanje postova tog statusa.','For post edit by a user who cannot publish, %sworkflow is configured%s to make the Publish button increment the post to the next workflow status permitted.'=>'Za uređivanje posta od strane korisnika koji ne može objaviti, %sworkflow je konfiguriran%s da gumb Objavi poveća post na sljedeći dopušteni status radnog tijeka.','For post edit by a user who cannot publish, %sworkflow is configured%s to make the Publish button escalate the post to the highest-ordered workflow status permitted.'=>'Za uređivanje posta od strane korisnika koji ne može objaviti, %sworkflow je konfiguriran%s da gumb Objavi eskalira post na najviši dopušteni status radnog tijeka.','For post edit by a user who cannot publish, the Publish button will escalate the post to the highest-order status permitted to the user.'=>'Za uređivanje posta od strane korisnika koji ne može objaviti, gumb Objavi će eskalirati post na najviši status dopušten korisniku.','Please enable the PublishPress %sStatuses feature%s.'=>'Molimo omogućite PublishPress %sStatusi značajku%s.','Note that the Post Type itself will also need to have %sPermissions%s enabled.'=>'Napomena da će se i sam tip posta također morati imati %sDozvole%s omogućene.','To disable custom visibility statuses, first re-assign posts to a different status.'=>'Da biste onemogućili prilagođene vidljivosti statuse, prvo ponovno dodijelite postove drugom statusu.','Note, this only applies if the role definition includes the pp_moderate_any capability'=>'Napomena, to se odnosi samo ako definicija uloge uključuje sposobnost pp_moderate_any','Create or edit custom Privacy or Workflow statuses.'=>'Izradite ili uredite prilagođene statusa privatnosti ili tijeka rada.','Create or edit custom Privacy statuses.'=>'Izradite ili uredite prilagođene statusa privatnosti.','Extra Roles created as a type-specific copy of this role will enable assignment of specified custom statuses.'=>'Dodatne uloge stvorene kao specifična kopija ove uloge omogućit će dodjelu određenih prilagođenih statusa.','Editors do not need status-specific editing capabilities for workflow posts (Assigned, In Progress, Approved).'=>'Urednici ne trebaju specifične sposobnosti uređivanja za postove radnog tijeka (Dodijeljeno, U tijeku, Odobreno).','If enabled, non-Editors will need to be granted editing access via the "Permissions" screen.'=>'Ako je omogućeno, ne-urednici će morati dobiti pristup uređivanju putem ekrana "Dozvole".','If enabled, a Visibility Status dropdown will appear in Quick Edit for easy status assignment.'=>'Ako je omogućeno, padajući izbornik Vidljivost Statusa pojavit će se u Brzom Uređivanju za jednostavno dodjeljivanje statusa.','If enabled, this will add Visibility Statuses support to the PublishPress Status plugin.'=>'Ako je omogućeno, ovo će dodati podršku za Vidljivost Statuse dodatku PublishPress Status.','Post property or meta field to match with user field'=>'Postavljanje svojstva ili meta polja za usklađivanje s korisničkim poljem','User property or meta field to match with post field'=>'Korisničko svojstvo ili meta polje za usklađivanje s poljem objave','User meta field to match with post field'=>'Korisničko meta polje za usklađivanje s poljem objave','User role to include in synchronization'=>'Korisnička uloga koju uključiti u sinkronizaciju','Parent id for created posts'=>'ID roditelja za stvorene objave','Choose post field from suggested meta key names'=>'Odaberite polje objave iz predloženih naziva meta ključeva','When a new user of specified role is added, create or designate a post for them.'=>'Kada se doda novi korisnik određene uloge, stvorite ili odredite objavu za njih.','Create or designate a post for existing users.'=>'Izradite ili odredite objavu za postojeće korisnike.','This post type is not hierarchical'=>'Ova vrsta objave nije hijerarhijska','Automatically create a post for each user in selected roles.'=>'Automatski stvorite objavu za svakog korisnika u odabranim ulogama.','Hint: If %s have custom fields (like email address), create one to assist field name discovery.'=>'Savjet: Ako %s imaju prilagođena polja (kao što je adresa e-pošte), stvorite jedno kako biste olakšali otkrivanje naziva polja.','Enable each user to edit their own User Posts.'=>'Omogućite svakom korisniku da uređuje svoje vlastite korisničke objave.','Settings for replacing unreadable content with teaser text, provided by the %s module.'=>'Postavke za zamjenu nečitljivog sadržaja s teaser tekstom, koje pruža %s modul.','Settings on this tab do not apply because teaser filtering is disabled for all post types.'=>'Postavke na ovoj kartici ne primjenjuju se jer je filtriranje teasera onemogućeno za sve vrste objava.','Since some browsers will cache feeds without regard to user login, block RSS content even for qualified users.'=>'Budući da neki preglednici keširaju feedove bez obzira na prijavu korisnika, blokirajte RSS sadržaj čak i za kvalificirane korisnike.','This feature controls what users will see when trying to view content they are blocked from accessing.'=>'Ova funkcija kontrolira što će korisnici vidjeti kada pokušaju pregledati sadržaj kojem nemaju pristup.','These settings adjust which views, link types and visibility statuses the teaser is applied to.'=>'Ove postavke prilagođavaju koje se prikaze, tipovi poveznica i statusi vidljivosti primjenjuju na teaser.','You can override Teaser settings within the Nav Menu by hiding links to unreadable posts that are associated with the terms you select below.'=>'Možete poništiti postavke teasera unutar izbornika navigacije skrivanjem poveznica na nečitljive objave koje su povezane s pojmovima koje odaberete u nastavku.','Keep unreadable content hidden in the blogroll and link lists, but show the teaser on direct access attempts.'=>'Skrivite nečitljiv sadržaj u blogrollu i popisima poveznica, ali prikažite teaser prilikom pokušaja izravnog pristupa.','Hide unreadable private posts, but show a teaser for posts which are unreadable due to regular Privacy or Role Restrictions.'=>'Skrivite nečitljive privatne objave, ali prikažite teaser za objave koje su nečitljive zbog redovitih ograničenja privatnosti ili uloge.','If anyone tries to view a post they don\'t have access to, redirect to another post instead of displaying a teaser.'=>'Ako netko pokuša pregledati objavu na koju nema pristup, preusmjerite ga na drugu objavu umjesto da prikažete teaser.','Replace post content or excerpt with custom text, possibly including an inline login form. You can also add text before or after the post title and excerpt.'=>'Zamijenite sadržaj objave ili izvadak s prilagođenim tekstom, moguće uključujući inline obrazac za prijavu. Također možete dodati tekst prije ili nakon naslova objave i izvatka.','Unreadable items of these comma-separated types will have nav menu item hidden.'=>'Nečitljivi elementi ovih tipova odvojenih zarezima imat će skriveni stavku izbornika navigacije.','Visibility Circle membership does not limit viewing access.'=>'Članstvo u Vidljivom Krugu ne ograničava pristup gledanju.','Editorial Circle membership does not limit editing access.'=>'Članstvo u Uredničkom Krugu ne ograničava pristup uređivanju.','When searching for users via Permissions ajax, return return only users registered to current site'=>'Kada tražite korisnike putem Permissions ajax, vratite samo korisnike registrirane na trenutnoj stranici.','If user is a super admin or has \'pp_manage_network_members\' capability, user searches via Permissions ajax return users from all sites'=>'Ako je korisnik super admin ili ima \'pp_manage_network_members\' sposobnost, pretraživanje korisnika putem Permissions ajax vraća korisnike sa svih stranica.','Count users as a member of a BuddyPress Permissions Group only if they are a moderator of the BP group'=>'Brojite korisnike kao članove BuddyPress Permissions Grupe samo ako su moderatori BP grupe.','Count users as a member of a BuddyPress Permissions Group only if they are an administrator of the BP group'=>'Brojite korisnike kao članove BuddyPress Permissions Grupe samo ako su administratori BP grupe.','CMS Page Tree View plugin: hide \'add\' links (for all hierarchical post types) based on user\'s association permissions'=>'CMS Page Tree View plugin: sakrijte \'dodaj\' poveznice (za sve hijerarhijske vrste objava) na temelju dopuštenja korisnika.','CMS Page Tree View plugin: hide \'add\' links (for pages) based on user\'s page association permissions'=>'CMS Page Tree View plugin: sakrijte \'dodaj\' poveznice (za stranice) na temelju dopuštenja korisnika za povezivanje sa stranicama.','CMS Page Tree View plugin: hide \'add\' links (for specified hierarchical post type) based on user\'s association permissions'=>'CMS Page Tree View plugin: sakrijte \'dodaj\' poveznice (za određenu hijerarhijsku vrstu objave) na temelju dopuštenja korisnika.','Prevent Permission from filtering the Nested Pages listing at all'=>'Spriječite da dozvole filtriraju popis Ugniježdenih stranica','Force Permissions to filter the Nested Pages listing'=>'Prisili dozvole da filtriraju popis Ugniježdenih stranica','Comma-separated list of roles that are allowed to Quick Edit nested pages'=>'Popis uloga odvojenih zarezima koje imaju pravo na Brzo uređivanje ugniježdenih stranica','Comma-separated list of roles that are allowed to use the Context Menu'=>'Popis uloga odvojenih zarezima koje imaju pravo na korištenje Kontekstnog izbornika','Never allow unfiltered users to use the Context Menu, even if they have pp_force_quick_edit capability'=>'Nikada ne dopuštajte nefiltriranim korisnicima korištenje kontekstnog izbornika, čak i ako imaju pp_force_quick_edit sposobnost','Disable Add Child link unless user is unfiltered (Administrator or has pp_nested_pages_unfiltered capability)'=>'Onemogućite poveznicu Dodaj dijete osim ako korisnik nije nefiltriran (Administrator ili ima pp_nested_pages_unfiltered sposobnost)','Disable Add Child Page link unless user is unfiltered'=>'Onemogući vezu Dodaj stranicu dijete osim ako korisnik nije filtriran','Disable Insert Page Before link unless user is unfiltered'=>'Onemogući vezu Umetni stranicu prije osim ako korisnik nije filtriran','Disable Insert Page After link unless user is unfiltered'=>'Onemogući vezu Umetni stranicu nakon osim ako korisnik nije filtriran','Disable Push to Top link unless user is unfiltered'=>'Onemogući vezu Pomiči na vrh osim ako korisnik nije filtriran','Disable Push to Bottom link unless user is unfiltered'=>'Onemogući vezu Pomiči na dno osim ako korisnik nije filtriran','Disable Clone link unless user is unfiltered'=>'Onemogući vezu Kloniraj osim ako korisnik nije filtriran','License'=>'Licenca','License Key'=>'Ključ licence','Version'=>'Verzija','settings'=>'postavke','Key Expired'=>'Ključ istekao','Deactivate Key'=>'Deaktiviraj ključ','Key Activated'=>'Ključ aktiviran','(please enter publishpress.com key)'=>'(molimo unesite publishpress.com ključ)','Activate Key'=>'Aktiviraj ključ','Note: Renewal does not require deactivation. If you do deactivate, re-entry of the license key will be required.'=>'Napomena: Obnova ne zahtijeva deaktivaciju. Ako deaktivirate, bit će potrebno ponovno unijeti ključ licence.','Your license key has expired. For continued priority support, %1$splease renew%2$s.'=>'Vaš licencni ključ je istekao. Za nastavak prioritetne podrške, %1$smolimo obnovite%2$s.','Your license key will expire today. For updates and priority support, %1$splease renew%2$s.'=>'Vaš licencni ključ će isteći danas. Za ažuriranja i prioritetnu podršku, %1$smolimo obnovite%2$s.','Your license key (for plugin updates) will expire in %1$d day(s). For updates and priority support, %2$splease renew%3$s.'=>'Vaš licencni ključ (za ažuriranja dodataka) će isteći za %1$d dan(a). Za ažuriranja i prioritetnu podršku, %2$smolimo obnovite%3$s.','For updates to Permissions Pro, activate your %1$sPublishPress license key%2$s.'=>'Za ažuriranja Permissions Pro, aktivirajte svoj %1$sPublishPress licencni ključ%2$s.','reload module info'=>'ponovno učitaj informacije o modulu','Permissions Pro Version: %1$s %2$s'=>'Pro verzija dozvola: %1$s %2$s','view %s&nbsp;details'=>'prikaži %s&nbsp;detalje','update check / install'=>'provjera ažuriranja 